const schema = {
  required: ['id', 'email', 'age'],
  properties: {
    id: { type: 'string' },
    email: { type: 'string' },
    age: { type: 'integer' }
  }
};

function typeOf(v) {
  if (Number.isInteger(v)) return 'integer';
  if (typeof v === 'number') return 'number';
  if (typeof v === 'string') return 'string';
  if (typeof v === 'boolean') return 'boolean';
  return typeof v;
}

function validate(schema, body) {
  const errors = [];
  for (const field of schema.required) {
    if (!(field in body)) errors.push('missing required field: ' + field);
  }
  for (const [field, def] of Object.entries(schema.properties)) {
    if (field in body) {
      const actual = typeOf(body[field]);
      if (actual !== def.type) {
        errors.push('type mismatch on ' + field + ': expected ' + def.type + ', got ' + actual);
      }
    }
  }
  return errors;
}

function report(body) {
  const errors = validate(schema, body);
  if (errors.length === 0) {
    console.log('VALID');
  } else {
    console.log('INVALID');
    for (const e of errors) console.log('  ' + e);
  }
}

report({ id: 'u1', email: 'a@b.co', age: 30 });
report({ id: 7, email: 'a@b.co' });
